s.data_purpose_code='PRODUCTION' AND s.provider_code IN

    CASE WHEN #{provider}='GOV24' THEN 'GOV24_PUBLIC_SERVICE' ELSE #{provider} END

AND s.collected_at>=#{collectedFrom} AND s.collected_at<#{collectedBefore}
AND s.application_end_date>=#{deadlineFrom}
AND s.application_end_date<=#{deadlineThrough}

mapper.select:
-- 목록과 집계는 같은 관리 범위를 사용한다.
SELECT  FROM announcement_attachment_batches WHERE scope_item_count IS NOT NULL
ORDER BY created_at DESC,id DESC LIMIT #{size} OFFSET #{offset}
